// Build the Claude prompt from the incoming message + conversation history
const body = $input.first().json.body || $input.first().json;
const sessionId = body.session_id;
const message = body.message;
const history = body.history || [];

const transcript = history
  .map(h => `${h.role === 'user' ? 'Customer' : 'Assistant'}: ${h.text}`)
  .join('\n');

const systemPrompt = `You are the AI assistant for PrimeHomes Realty, a real estate company.
You act like a friendly, efficient receptionist collecting information from a potential customer (a "lead").

Your job on every turn:
1. Read the full conversation so far.
2. Extract any of these fields you can find, across the WHOLE conversation (not just the latest message): name, email, phone, property_type (apartment/house/land/commercial/office/shop), bedrooms (number), location, budget (a number in Naira, no symbols/commas), buy_or_rent ("buy" or "rent"), intent ("buying"|"renting"|"selling"|"land"|"enquiry"), timeline ("immediate"|"1_month"|"3_months"|"researching").
3. Write a short, warm, natural reply that either asks ONE clear follow-up question for the most important missing field, or, if you have enough information (at least property_type, location, budget, and intent), confirms the details back and lets them know a specialist will reach out.
4. Never invent information the customer didn't give you. Use null for anything unknown.

Respond with ONLY valid JSON, no markdown fences, no commentary, in exactly this shape:
{
  "extracted": {
    "name": string|null,
    "email": string|null,
    "phone": string|null,
    "property_type": string|null,
    "bedrooms": number|null,
    "location": string|null,
    "budget": number|null,
    "buy_or_rent": string|null,
    "intent": string|null,
    "timeline": string|null
  },
  "missing_fields": string[],
  "reply": string
}`;

const userContent = `Conversation so far:\n${transcript}\n\nLatest customer message: "${message}"\n\nReturn the JSON now.`;

return [{
  json: {
    session_id: sessionId,
    message,
    system_prompt: systemPrompt,
    user_content: userContent
  }
}];

// Parse Claude's JSON response and merge it onto the session/message from the previous node
const prev = $('Build Prompt').first().json;
const aiRaw = $input.first().json;

let text = aiRaw.content?.[0]?.text || '{}';
text = text.trim().replace(/^```json/, '').replace(/^```/, '').replace(/```$/, '').trim();

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = { extracted: {}, missing_fields: [], reply: "Thanks for reaching out — could you tell me a bit more about what you're looking for?" };
}

const extracted = parsed.extracted || {};

return [{
  json: {
    session_id: prev.session_id,
    last_message: prev.message,
    reply: parsed.reply,
    missing_fields: parsed.missing_fields || [],
    ...extracted
  }
}];

// Simple lead scoring rubric (from the class rules):
// phone +10, budget +20, location +15, property_type +15, buying soon +25, clear requirements +15
const d = $input.first().json;

let score = 0;
if (d.phone) score += 10;
if (d.budget) score += 20;
if (d.location) score += 15;
if (d.property_type) score += 15;
if (d.timeline === 'immediate' || d.timeline === '1_month') score += 25;

const requiredForClear = ['property_type', 'location', 'budget', 'intent'];
const hasClearRequirements = requiredForClear.every(f => d[f] !== null && d[f] !== undefined && d[f] !== '');
if (hasClearRequirements) score += 15;

score = Math.min(score, 100);

let status;
if (score >= 80) status = 'HOT';
else if (score >= 50) status = 'WARM';
else status = 'COLD';

return [{ json: { ...d, score, status } }];
